class Solution {
    public ListNode reverseKGroup(ListNode head, int k) {
        ListNode dummy = new ListNode(0, head);
        ListNode groupPrev = dummy;

        while (true) {
            ListNode kth = getKth(groupPrev, k);
            if (kth == null) {
                break;
            }

            ListNode groupNext = kth.next;
            ListNode prev = groupNext;
            ListNode curr = groupPrev.next;
            while (curr != groupNext) {
                ListNode next = curr.next;
                curr.next = prev;
                prev = curr;
                curr = next;
            }

            ListNode oldGroupHead = groupPrev.next;
            groupPrev.next = kth;
            groupPrev = oldGroupHead;
        }

        return dummy.next;
    }

    private ListNode getKth(ListNode start, int k) {
        while (start != null && k > 0) {
            start = start.next;
            k--;
        }
        return start;
    }
}

class Solution {
    public ListNode reverseKGroup(ListNode head, int k) {
        ListNode dummy = new ListNode(0, head);
        ListNode groupPrev = dummy;

        while (true) {
            ListNode kth = groupPrev;
            for (int i = 0; i < k && kth != null; i++) {
                kth = kth.next;
            }
            if (kth == null) {
                break;
            }

            ListNode groupTail = groupPrev.next;
            ListNode curr = groupTail.next;
            for (int i = 1; i < k; i++) {
                groupTail.next = curr.next;
                curr.next = groupPrev.next;
                groupPrev.next = curr;
                curr = groupTail.next;
            }
            groupPrev = groupTail;
        }

        return dummy.next;
    }
}

class Solution {
    public ListNode reverseKGroup(ListNode head, int k) {
        ListNode node = head;
        for (int i = 0; i < k; i++) {
            if (node == null) {
                return head;
            }
            node = node.next;
        }

        ListNode reversedHead = reverseFirstK(head, k);
        head.next = reverseKGroup(node, k);
        return reversedHead;
    }

    private ListNode reverseFirstK(ListNode head, int k) {
        ListNode prev = null;
        ListNode curr = head;
        for (int i = 0; i < k; i++) {
            ListNode next = curr.next;
            curr.next = prev;
            prev = curr;
            curr = next;
        }
        return prev;
    }
}

import java.util.*;

class Solution {
    public ListNode reverseKGroup(ListNode head, int k) {
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        ListNode curr = head;

        while (curr != null) {
            Deque<ListNode> stack = new ArrayDeque<>();
            ListNode groupStart = curr;
            int count = 0;

            while (count < k && curr != null) {
                stack.push(curr);
                curr = curr.next;
                count++;
            }

            if (count < k) {
                tail.next = groupStart;
                break;
            }

            while (!stack.isEmpty()) {
                tail.next = stack.pop();
                tail = tail.next;
            }
            tail.next = curr;
        }

        return dummy.next;
    }
}
